int getRank()
{
    int rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    return rank;
}

int getSize()
{
    int size;
    MPI_Comm_size(MPI_COMM_WORLD, &size);
    return size;
}

extern void mpi_initialize() {
    MPI_Init(NULL, NULL);
    initialize_mpi_types();
}

extern void mpi_finalize() {
    cout << "Ending Communication from Rank " << getRank() << endl;
    MPI_Finalize();
}
